-- ResQPartido — jurisdiction routing
-- Run this in the Supabase SQL editor AFTER response_tracking_schema.sql.
-- Safe to re-run.
--
-- What it does: every report is assigned to the municipality where the
-- emergency physically IS (from its GPS coordinates), not the municipality
-- on the citizen's account. A dispatcher then only sees, and can only act
-- on, reports in their own municipality:
--
--   citizen from San Jose presses SOS while in Goa
--     -> incident.jurisdiction = 'Goa'
--     -> Goa dispatchers (every agency: PNP, BFP, MDRRMO) see it;
--        San Jose dispatchers do not.
--
-- This is enforced by row-level security in the database, not just hidden in
-- the console, so it holds no matter which app or API call reads the data.
--
-- Reports that fall outside all five municipalities, or have no usable GPS,
-- get jurisdiction = NULL and are visible to EVERY dispatcher — an
-- emergency is never dropped because it couldn't be placed.
--
-- Boundaries: Philippine Statistical Authority municipal boundaries (PSGC,
-- 31 Dec 2023) via github.com/faeldon/philippines-json-maps (MIT), lightly
-- simplified to ~16 m. Stored as built-in Postgres polygons, so no PostGIS
-- extension is needed.

-- ---------------------------------------------------------------
-- 1. Municipal boundaries
--    Names match the app's own list (lib/alertTypes.js MUNICIPALITIES),
--    including its "Sangay" spelling for Sagñay.
-- ---------------------------------------------------------------
create table if not exists public.municipality_boundaries (
  id serial primary key,
  municipality text not null,
  boundary polygon not null   -- (longitude, latitude) pairs
);

alter table public.municipality_boundaries enable row level security;

drop policy if exists "municipality_boundaries: dispatcher read" on public.municipality_boundaries;
create policy "municipality_boundaries: dispatcher read" on public.municipality_boundaries
  for select using (public.is_dispatcher());

truncate public.municipality_boundaries restart identity;

insert into public.municipality_boundaries (municipality, boundary) values
