-- 2. Which municipality is this point in?
--    Inside a boundary -> that municipality. Otherwise the nearest one
--    within ~1.5 km, which absorbs GPS drift at borders and on the coast.
--    Anything farther out -> NULL (visible to all dispatchers).
--    Also called by the dispatcher console (rpc) to decide whether a
--    citizen's live call should ring for this dispatcher.
-- ---------------------------------------------------------------
create or replace function public.jurisdiction_at(p_lat double precision, p_lng double precision)
returns text
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select b.municipality
       from public.municipality_boundaries b
      where point(p_lng, p_lat) <@ b.boundary
      limit 1),
    (select b.municipality
       from public.municipality_boundaries b
      where point(p_lng, p_lat) <-> b.boundary <= 0.0135
      order by point(p_lng, p_lat) <-> b.boundary
      limit 1)
  )
  where p_lat is not null and p_lng is not null
    and p_lat between -90 and 90 and p_lng between -180 and 180;
$$;

revoke all on function public.jurisdiction_at(double precision, double precision) from public, anon;
grant execute on function public.jurisdiction_at(double precision, double precision) to authenticated;

-- ---------------------------------------------------------------
-- 3. Access rule used by every policy below.
--    admin      -> everything
--    dispatcher -> rows in their own profile municipality, plus rows with
--                  no jurisdiction. A dispatcher account with NO municipality
--                  set sees only the unassigned rows (fails closed) — set it
--                  in Manage Accounts.
--    anyone else -> nothing (a citizen still sees their own reports through
--                  the citizen app's own policies).
-- ---------------------------------------------------------------
create or replace function public.can_access_jurisdiction(j text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
      from public.profiles p
     where p.id = auth.uid()
       and (
         p.role = 'admin'
         or (
           p.role = 'dispatcher'
           and (j is null or lower(btrim(p.municipality)) = lower(btrim(j)))
         )
       )
  );
$$;

-- ---------------------------------------------------------------
-- 4. Incidents: stamp the jurisdiction server-side, then scope access to it.
-- ---------------------------------------------------------------
alter table public.incidents add column if not exists jurisdiction text;
create index if not exists incidents_jurisdiction_idx on public.incidents (jurisdiction);

-- Computed from the coordinates on insert (and if the coordinates change),
-- never taken from the client — nobody can route a report to a different
-- municipality by sending a different value. Reports that are still
-- unplaced are retried on their next update.
create or replace function public.assign_incident_jurisdiction()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'INSERT'
     or new.latitude is distinct from old.latitude
     or new.longitude is distinct from old.longitude
     or old.jurisdiction is null then
    new.jurisdiction := public.jurisdiction_at(new.latitude, new.longitude);
  else
    new.jurisdiction := old.jurisdiction;
  end if;
  return new;
end;
$$;

drop trigger if exists assign_incident_jurisdiction on public.incidents;
create trigger assign_incident_jurisdiction
  before insert or update on public.incidents
  for each row execute function public.assign_incident_jurisdiction();

-- Place the reports that already exist.
update public.incidents
   set jurisdiction = public.jurisdiction_at(latitude, longitude)
 where jurisdiction is null;

-- Replace the "every dispatcher sees every report" policies from
-- dispatcher_schema.sql.
drop policy if exists "incidents: dispatcher read all" on public.incidents;
drop policy if exists "incidents: dispatcher update status" on public.incidents;
drop policy if exists "incidents: dispatcher read jurisdiction" on public.incidents;
drop policy if exists "incidents: dispatcher update jurisdiction" on public.incidents;

create policy "incidents: dispatcher read jurisdiction" on public.incidents
  for select using (public.can_access_jurisdiction(jurisdiction));

create policy "incidents: dispatcher update jurisdiction" on public.incidents
  for update using (public.can_access_jurisdiction(jurisdiction))
  with check (public.can_access_jurisdiction(jurisdiction));

-- ---------------------------------------------------------------
-- 5. Incident media follows its incident. The foreign-key column name lives
--    in the citizen app's schema, so it is looked up rather than assumed.
-- ---------------------------------------------------------------
drop policy if exists "incident_media: dispatcher read all" on public.incident_media;
drop policy if exists "incident_media: dispatcher read jurisdiction" on public.incident_media;

do $$
declare
  fk_col text;
begin
  select a.attname
    into fk_col
    from pg_constraint c
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
   where c.conrelid = 'public.incident_media'::regclass
     and c.confrelid = 'public.incidents'::regclass
     and c.contype = 'f'
   limit 1;

  if fk_col is null then
    raise exception 'incident_media has no foreign key to incidents; cannot scope media by jurisdiction';
  end if;

  -- The sub-select runs under incidents' own row-level security, so a
  -- dispatcher only gets media for reports they can already see.
  execute format(
    'create policy "incident_media: dispatcher read jurisdiction" on public.incident_media
       for select using (
         public.is_dispatcher()
         and exists (select 1 from public.incidents i where i.id = incident_media.%I)
       )', fk_col);
end $$;

-- ---------------------------------------------------------------
-- 6. Call history follows the same rule. A call's jurisdiction is the
--    municipality of the report it was about, or — for a citizen calling in —
--    where that citizen was calling from. Calls with none are visible to all.
-- ---------------------------------------------------------------
alter table public.call_logs add column if not exists jurisdiction text;
create index if not exists call_logs_jurisdiction_idx on public.call_logs (jurisdiction);

update public.call_logs c
   set jurisdiction = i.jurisdiction
  from public.incidents i
 where c.incident_id = i.id
   and c.jurisdiction is null;

drop policy if exists "call_logs: dispatcher read all" on public.call_logs;
drop policy if exists "call_logs: dispatcher update" on public.call_logs;
drop policy if exists "call_logs: dispatcher read jurisdiction" on public.call_logs;
drop policy if exists "call_logs: dispatcher update jurisdiction" on public.call_logs;

create policy "call_logs: dispatcher read jurisdiction" on public.call_logs
  for select using (public.can_access_jurisdiction(jurisdiction));

create policy "call_logs: dispatcher update jurisdiction" on public.call_logs
  for update using (public.can_access_jurisdiction(jurisdiction))
  with check (public.can_access_jurisdiction(jurisdiction));
